package com.aroos.qr.generator.ec;

import static org.assertj.core.api.Assertions.assertThat;

import org.testng.annotations.Test;

import com.aroos.qr.generator.common.BitStream;
import com.aroos.qr.generator.common.IBitStream;
import com.aroos.qr.generator.common.QRConfiguration;
import com.aroos.qr.generator.common.services.Codewords;
import com.aroos.qr.generator.encoding.EncodingMode;

public final class ErrorCorrectionEncoderTest
{
    private static String EXPECTED = "";

    private static byte[] CODEWORDS = new byte[] {
        0b01000011,
        0b01010101,
        0b01000110,
        (byte)0b10000110,
        0b01010111,
        0b00100110,
        0b01010101,
        (byte)0b11000010,
        0b01110111,
        0b00110010,
        0b00000110,
        0b00010010,
        0b00000110,
        0b01100111,
        0b00100110,
        (byte)0b11110110,
        (byte)0b11110110,
        0b01000010,
        0b00000111,
        0b01110110,
        (byte)0b10000110,
        (byte)0b11110010,
        0b00000111,
        0b00100110,
        0b01010110,
        0b00010110,
        (byte)0b11000110,
        (byte)0b11000111,
        (byte)0b10010010,
        0b00000110,
        (byte)0b10110110,
        (byte)0b11100110,
        (byte)0b11110111,
        0b01110111,
        0b00110010,
        0b00000111,
        0b01110110,
        (byte)0b10000110,
        0b01010111,
        0b00100110,
        0b01010010,
        0b00000110,
        (byte)0b10000110,
        (byte)0b10010111,
        0b00110010,
        0b00000111,
        0b01000110,
        (byte)0b11110111,
        0b01110110,
        0b01010110,
        (byte)0b11000010,
        0b00000110,
        (byte)0b10010111,
        0b00110010,
        (byte)0b11100000,
        (byte)0b11101100,
        0b00010001,
        (byte)0b11101100,
        0b00010001,
        (byte)0b11101100,
        0b00010001,
        (byte)0b11101100
    };

    @Test
    public void ecCodewordsTest()
    {
        final IBitStream testMessage = new BitStream();
        final QRConfiguration config = new QRConfiguration(5, ErrorCorrectionLevel.LEVEL_Q, EncodingMode.BYTE);

        for (final byte b : CODEWORDS)
        {
            testMessage.putByte(b);
        }

        final IErrorCorrectionEncoder encoder = new ErrorCorrectionEncoder(new Codewords());
        
        final IBitStream result = encoder.encode(testMessage, config);

        assertThat(result.toString())
            .isEqualTo(EXPECTED);
    }    
}